class DataHandler {
    int cache_ = 0;
public:
    // Overload 1: Takes a modifiable reference
    // Allows modification of the caller's argument
    void handle(int& value) {
        value *= 2;
        cache_ = 1;
    }

    // Overload 2: Takes a const reference
    // Read-only access to the caller's argument
    void handle(const int& value) const {
        // value *= 2; // ERROR: read-only
        // cache_ = 2; // ERROR: member function is const
    }
};
